const b = $json.body || {};
const p = String(b.prompt || '').trim();
const m = p.match(/^\/([a-z0-9-]+)\s*([\s\S]*)$/i);
return [{ json: {
  prompt: p,
  user: b.user || '',
  command: m ? m[1].toLowerCase() : '',
  args: m ? m[2].trim() : '',
  hasCommand: !!m
} }];

const cmd = $node['Parse command'].json.command;
let out = $json;
if (out && typeof out === 'object' && 'body' in out) out = out.body;
const detail = typeof out === 'object' ? JSON.stringify(out, null, 2) : String(out || '');
return [{ json: { response: `Triggered \`/${cmd}\`.\n\n${detail}`.trim() } }];
